import {cabinPressure,pressureReady,dockCanLaunch} from '../shared/dock-rules.js';
import {createStation} from '../shared/station-art.js';
import {T,engine,batchStatic,box,sphere,cylinder,line,label} from '../shared/engine.js';
import {shell,load,save,toast,modal,lifecycle,tone,bindHold,clamp} from '../shared/core.js';
export function mountDock(){shell('Afterlight','SECTOR 08 · ORBITAL DOCKS');const e=engine({sky:0x071421,fog:160}),s=e.scene;const art=createStation(e,{variant:'dock'}),{fuse,screen,bridge,beam,recorder,astronaut}=art;
const beam2=box(s,67,1.7,0,.12,3.4,4.5,0xf2a871);beam2.material.dispose();beam2.material=new T.MeshBasicMaterial({color:0xffa365,transparent:true,opacity:.5,depthWrite:false});for(const z of [-2.4,2.4])cylinder(s,67,1.8,z,.2,.23,3.6,0x77898d);label(s,'DOCK SECURITY',63,4.2,-2,{size:6});
const initial={x:2,fuse:false,power:false,complete:false,log:false,checkpoint:2,relays:[0,0,0]};let state=load('afterlight:dock',initial);if(state.complete)state={...initial,relays:[0,0,0]};let saveTime=0,coyote=.12,jumpBuffer=0,vx=0;let x=state.x,y=0,vy=0,left=false,right=false,grounded=true,timer=0,checkpoint=state.checkpoint??(state.power?29:2),finished=false;fuse.visible=!state.fuse;bridge.visible=state.power;recorder.visible=!state.log;
document.querySelector('#controls').innerHTML='<div class="control-panel"><button class="hold" id="left" aria-label="Move left">‹</button><button class="hold" id="right" aria-label="Move right">›</button></div><div class="control-note">Move · jump · inspect.<br>Watch the pulse before crossing.</div><div class="control-panel"><button id="interact">Inspect</button><button class="hold primary" id="jump" aria-label="Jump">↑</button></div>';const persist=()=>{state.x=grounded?x:checkpoint;state.checkpoint=checkpoint;save('afterlight:dock',state)};for(const [id,set]of [['left',v=>left=v],['right',v=>right=v]])bindHold(document.querySelector('#'+id),()=>set(true),()=>set(false));const jump=()=>{if(!life.paused()){jumpBuffer=.16}};document.querySelector('#jump').onpointerdown=jump;
function relay(){const d=modal('Life-support manifold',`<p>${state.fuse?'The scrubber cartridge is installed.':'A scrubber cartridge is missing. Find it near the start.'} Bring cabin pressure to <strong>100</strong>.</p><p>Each valve setting runs from 0–3:<br>Intake adds 30 per step. Scrubber adds 20. Bypass removes 10.<br>Scrubber must be at least 2; bypass must remain at least 1.</p><div id="dockvalves" class="puzzle-row"></div><p id="pressure"></p>`,[{text:'Pressurise dock',close:false,action:()=>{if(pressureReady(state)){state.power=true;checkpoint=29;bridge.visible=true;persist();d.remove();toast('Pressure stable · cargo bridge unlocked');tone(660,.3)}else d.querySelector('#pressure').textContent=!state.fuse?'Collect the scrubber cartridge first.':'Check pressure and the scrubber/bypass minimums.'}},{text:'Back'}]);const refresh=()=>d.querySelector('#pressure').textContent='Cabin pressure: '+cabinPressure(state.relays)+' / 100';for(let i=0;i<3;i++){const b=document.createElement('button');const show=()=>b.textContent=['Intake','Scrubber','Bypass'][i]+': '+state.relays[i];show();b.onclick=()=>{state.relays[i]=(state.relays[i]+1)%4;show();refresh();persist()};d.querySelector('#dockvalves').append(b)}refresh()}
function interact(){if(life.paused())return;if(Math.abs(x-11)<3&&!state.fuse){state.fuse=true;fuse.visible=false;persist();toast('Scrubber cartridge collected · restore life support');tone(700,.18)}else if(Math.abs(x-28)<3){relay()}else if(Math.abs(x-64)<3&&!state.log){state.log=true;recorder.visible=false;persist();modal('A course for home','<p>The navigation core contains a safe descent corridor. Carry it to the escape pod beyond the second security gate.</p><p><strong>Navigation core recovered.</strong></p>')}else if(Math.abs(x-73)<3){if(!dockCanLaunch(state)){toast(!state.power?'Restore cabin pressure before launching.':'Recover the navigation core before launching.');return}finished=true;state.complete=true;persist();modal('Homeward',`<p>The pod clears the station. Cloud tops brighten beneath the glass.</p><p><strong>Both sectors complete.</strong> You restored the gantry, stabilised life support and recovered a route home.</p>`,[{text:'Studio',action:()=>location.hash=''},{text:'Replay orbital docks',action:()=>{save('afterlight:dock',initial);location.reload()}},{text:'Replay both sectors',action:()=>{save('afterlight',null);save('afterlight:dock',null);location.reload()}}])}else toast(x<20?'Find the scrubber cartridge near the first cargo stack.':x<40?'Balance the three life-support valves at the console.':x<62?'Two security gates alternate. Wait for a clear pulse.':'Collect the navigation core, then cross the last gate to the pod.')}
document.querySelector('#interact').onclick=interact;const kd=ev=>{if(['ArrowLeft','ArrowRight','ArrowUp',' ','a','d','w','e'].includes(ev.key)){ev.preventDefault();if(['a','ArrowLeft'].includes(ev.key))left=true;if(['d','ArrowRight'].includes(ev.key))right=true;if(['w','ArrowUp',' '].includes(ev.key))jump();if(ev.key==='e'&&!ev.repeat)interact()}};const ku=ev=>{if(['a','ArrowLeft'].includes(ev.key))left=false;if(['d','ArrowRight'].includes(ev.key))right=false};addEventListener('keydown',kd);addEventListener('keyup',ku);const release=()=>{left=right=false;vx=0;jumpBuffer=0};addEventListener('blur',release);const life=lifecycle({pause:release,reset:()=>save('afterlight:dock',initial)});if(!load('intro:afterlight:dock',false))modal('The orbital docks',`<p>The escape pod needs a pressurised dock and a navigation core. Restore life support, then pass two alternating security gates.</p><p>Use the arrows to move, ↑ to jump, and <strong>Inspect</strong> near objects. On a keyboard: A/D, Space, and E.</p>`,[{text:'Enter Sector 08',action:()=>save('intro:afterlight:dock',true)}]);e.start((dt,t)=>{if(!life.paused()&&!finished){timer+=dt;const move=(right?1:0)-(left?1:0),old=x;coyote=grounded?.12:Math.max(0,coyote-dt);jumpBuffer=Math.max(0,jumpBuffer-dt);if(jumpBuffer>0&&coyote>0){vy=7.7;grounded=false;jumpBuffer=coyote=0;tone(240,.07)}vx+=(move*6.5-vx)*(1-Math.exp(-dt*(grounded?14:7)));x=clamp(x+vx*dt,1,74);for(const b of [{x:20,w:1.45,h:1.65},{x:57,w:1.3,h:1.15}])if(Math.abs(x-b.x)<b.w&&y<b.h)x=old;vy-=16*dt;y+=vy*dt;const gap=x>35.5&&x<40.5&&!state.power;const floor=Math.abs(x-20)<1.35?1.7:Math.abs(x-57)<1.2?1.2:0;if(!gap&&y<=floor&&vy<=0){y=floor;vy=0;grounded=true}else grounded=false;if(y<-5){x=checkpoint;y=0;vy=vx=0;toast('Emergency tether recovered you · try again')}const beamOn=timer%5<2.8;beam.visible=beamOn;beam2.visible=(timer+2.5)%5<2.8;if((beamOn&&Math.abs(x-49)<.6)||(beam2.visible&&Math.abs(x-67)<.6)){x=checkpoint;y=0;vy=vx=0;toast('Security pulse · wait until the beam switches off');tone(120,.2)}if(x>54&&checkpoint<55){checkpoint=55;persist();toast('Airlock approach · checkpoint saved')}saveTime+=dt;if(grounded&&saveTime>.75){persist();saveTime=0}}recorder.rotation.y=t*.7;recorder.position.y=1.1+Math.sin(t*2)*.12;fuse.rotation.y=t;fuse.position.y=1+Math.sin(t*2)*.12;art.update({x,y,vx,grounded,t,power:state.power});const portrait=innerHeight>innerWidth;const cam=new T.Vector3(x+(portrait?2:3),portrait?4.6:3.5,portrait?18.5:13.8);e.camera.position.lerp(cam,1-Math.exp(-dt*5));e.camera.lookAt(x+(portrait?1:3),1.5,0);document.querySelector('#stat').textContent=!state.fuse?'Find the scrubber cartridge':!state.power?'Restore cabin pressure · target 100':x<54?'Gate one: '+(beam.visible?'ACTIVE':'CLEAR'):!state.log?'Recover the navigation core':'Gate two: '+(beam2.visible?'ACTIVE':'CLEAR')+' · escape pod ahead';document.querySelector('#interact').textContent=Math.abs(x-11)<3&&!state.fuse?'Collect':Math.abs(x-28)<3?'Console':Math.abs(x-64)<3&&!state.log?'Nav core':Math.abs(x-73)<3?'Launch':'Inspect'});return {dispose(){persist();life.dispose();art.dispose();e.dispose();removeEventListener('keydown',kd);removeEventListener('keyup',ku);removeEventListener('blur',release)}}}
